SELECT coalesce(jsonb_agg(jsonb_build_object('line',to_jsonb(l),'document',to_jsonb(d)) ORDER BY l.id),'[]') FROM receiving_document_lines l JOIN receiving_documents d ON d.tenant_id=l.tenant_id AND d.id=l.receiving_document_id WHERE l.tenant_id=?::uuid AND l.account_catalog_item_id=?::uuid AND EXISTS(SELECT 1 FROM jsonb_each_text(l.raw_data)kv WHERE lower(kv.key) IN('upc','ean','gtin','barcode') AND nullif(trim(kv.value),'') IS NOT NULL);
